public static TFMDataCacheProvider instance()
{
    TFMDataCacheProvider   provider;
    System.Runtime.Caching.ObjectCache memCache = System.Runtime.Caching.MemoryCache::Default;
    str cacheId = classId2Name(classIdGet(provider));
    provider = memCache.Get(cacheId);
    System.Collections.Generic.List<str> cacheIdList = new System.Collections.Generic.List<str>();
    cacheIdList.add(cacheId);
    System.Collections.IEnumerable cacheIdListEnumuable = cacheIdList;
    System.Runtime.Caching.CacheEntryChangeMonitor d = memCache.CreateCacheEntryChangeMonitor(cacheIdListEnumuable);

    if(!provider || d.IsDisposed)
    {
        provider = new TFMDataCacheProvider();
        memCache.Add(cacheId, provider, new System.Runtime.Caching.CacheItemPolicy());
    }

    return provider;
}

    public void new()
    {
        dataCache = new Map(Types::String, Types::Class);
	}

	public void addRecord(str _domain, str _key, Common _record)
    {
        Map recordCache = dataCache.exists(_domain) ? dataCache.lookup(_domain) : new Map (Types::String,Types::Record);
        recordCache.insert(_key, _record);
        dataCache.insert(_domain,recordCache);
    }

    public void removeRecord(str _domain, str _key)
    {
        Map recordCache = dataCache.exists(_domain) ? dataCache.lookup(_domain) : null;
		if (!recordCache)
        {
            return;
        }
        recordCache.remove(_key);
    }

public Common getRecord(str _domain, str _key)
{
    Map recordCache = dataCache.exists(_domain) ? dataCache.lookup(_domain) : null;
    if (!recordCache)
    {
        return null;
    }

    return recordCache.exists(_key) ? recordCache.lookup(_key) : null;
}
